-- ============================================================================
-- 0003_ac203_content.sql  —  AC-203 (the flagship) authored course content.
--
-- WIRING goal: replace the AC-203 placeholders with the authored lessons, the 12
-- knowledge-check items, the 4 new 2D sims + the device-config virtual-door build,
-- the RE-CENTERED egress branching sim (off the fire-alarm climax onto the power-loss
-- + push-to-exit ≥ 30 s release), and the §5.4 rubric swap (remove the fire-alarm-
-- release line, add the armature-seal pull-test line). 1-for-1 critical swap — AC-203
-- stays 12 rubric lines / 7 critical, so the safety veto set never shrinks (Inv. 1).
--
-- FORWARD-ONLY + IDEMPOTENT. Runs AFTER 0001 + 0002 (CI slice-seed job + config.toml
-- [db.seed]). 0001/0002 are immutable; all AC-203 content changes live here and may be
-- re-applied safely (UPSERT / DELETE-then-INSERT are idempotent). Byte-identical copy
-- at /seed/0003_ac203_content.sql. NO schema change — types do not regenerate.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. AC-203 knowledge-check UNIT (new) + de-placeholder the existing units.
--    ord 1-4 are the lesson / branching scenario / virtual-door sim / signoff_prep;
--    the KC unit takes a NEW ordinal (5). The grader resolves items by course_version_id.
-- ----------------------------------------------------------------------------
insert into academy.units (id, course_version_id, ordinal, title, kind, competency_id, est_minutes, content_ref) values
  ('000000c3-000e-0000-0000-000000000005', '000000c2-0000-0000-0000-00000000000e', 5, 'Mag-Lock, REX & Egress Knowledge Check', 'knowledge_check', '000000c0-0000-0000-0000-00000000000f', 15, '{"item_set":"ac-203","gate":0.90}'::jsonb)
on conflict (id) do update set
  course_version_id = excluded.course_version_id, ordinal = excluded.ordinal, title = excluded.title,
  kind = excluded.kind, competency_id = excluded.competency_id, est_minutes = excluded.est_minutes,
  content_ref = excluded.content_ref;

-- De-placeholder the lesson (u1) and the two mandatory sim units; switch the u3 build
-- from the unbuilt webgl_install engine to the device_config "virtual door" runtime.
update academy.units set content_ref = '{"mdx_key":"ac-203/u1"}'::jsonb
  where id = '000000c3-000e-0000-0000-000000000001';
update academy.units set content_ref = '{"engine":"branching_scenario","spec_key":"ac-203/egress-compliant","mandatory":true,"gate":0.90}'::jsonb
  where id = '000000c3-000e-0000-0000-000000000002';
update academy.units set content_ref = '{"engine":"device_config","spec_key":"ac-203/virtual-door-maglock","gate":0.90}'::jsonb
  where id = '000000c3-000e-0000-0000-000000000003';
update academy.units set content_ref = '{"signoff_rubric_template_ref":"academy.signoff_line_item_templates","course":"AC-203","gate_note":"EGRESS HARD GATE — safety-veto rubric; a single 0 on any ⚠ critical-safety line is an automatic fail (Inv. 1)."}'::jsonb
  where id = '000000c3-000e-0000-0000-000000000004';

-- ----------------------------------------------------------------------------
-- 2. The 12 real AC-203 knowledge-check items (replace the 4 S1 placeholders,
--    add 8 more). is_safety_item per the pack: items 3, 9, 10 = non-safety (80%);
--    the rest = safety (90%) — so BOTH mastery bars are exercised. UPSERT on id so a
--    re-seed over the existing placeholders reflects the authored content.
-- ----------------------------------------------------------------------------
insert into academy.assessment_items (id, competency_id, course_version_id, kind, prompt, options, answer_key, is_safety_item, mastery_weight, locale_variants) values
  ('000000a5-000e-0000-0000-000000000001', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"A mag lock holds the door shut by…","rationale":"Mag = powered to lock; lose power and it releases — that’s fail-safe."}'::jsonb, '{"choices":[{"id":"a","text":"being powered (energized to lock)"},{"id":"b","text":"losing power"},{"id":"c","text":"a mechanical latch"},{"id":"d","text":"the REX"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000002', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"On the Redex 1200S install, the lock’s Red lead lands on…","rationale":"Red → controller NC: 24V through the controller when locked, 0V (relay opens) when unlocked."}'::jsonb, '{"choices":[{"id":"a","text":"NC on the Alarm.com controller"},{"id":"b","text":"24V on the power supply"},{"id":"c","text":"a controller Input"},{"id":"d","text":"ground"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000003', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"The lock’s Black lead lands on…","rationale":"Black → 24V supply; Red → controller NC."}'::jsonb, '{"choices":[{"id":"a","text":"24V on the power supply"},{"id":"b","text":"NC on the controller"},{"id":"c","text":"ground"},{"id":"d","text":"a controller Input"}]}'::jsonb, '{"correct":"a"}'::jsonb, false, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000004', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"Locked, you meter the controller output and should read…","rationale":"Locked = 24V through the controller; 0V = unlocked (the relay has opened)."}'::jsonb, '{"choices":[{"id":"a","text":"24V (0V means unlocked)"},{"id":"b","text":"0V"},{"id":"c","text":"12V"},{"id":"d","text":"an open circuit"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000005', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"The push-to-exit is wired so that…","rationale":"No — that’s a REX. The push-to-exit is in-line in the mag power and cuts the lock’s power directly."}'::jsonb, '{"choices":[{"id":"a","text":"power runs through it before the mag, so pressing it cuts mag power directly"},{"id":"b","text":"it signals the controller to release, like a REX"},{"id":"c","text":"it arms the alarm panel"},{"id":"d","text":"it only logs an exit event"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000006', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"A motion REX alone is a code-compliant release for a mag lock — true or false?","rationale":"A motion REX alone is not code-compliant; the manual push-to-exit is always required."}'::jsonb, '{"choices":[{"id":"a","text":"False — the manual push-to-exit is still required"},{"id":"b","text":"True"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000007', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'multi_select', '{"text":"Select every requirement for the push-to-exit placement and release.","rationale":"NFPA 101 §7.2.1.6.2: 40–48 in, within 5 ft, releases ≥ 30 s, signed. Out of reach or momentary fails."}'::jsonb, '{"choices":[{"id":"a","text":"40–48 in above the floor"},{"id":"b","text":"within 5 ft of the door"},{"id":"c","text":"releases for at least 30 seconds"},{"id":"d","text":"mounted high by the panel, out of casual reach"},{"id":"e","text":"a momentary release only while held"}]}'::jsonb, '{"correct":["a","b","c"]}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000008', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"The armature plate should be mounted…","rationale":"Torqued solid is the silent-failure mistake: no seal, half the hold, and nothing on the panel warns you."}'::jsonb, '{"choices":[{"id":"a","text":"Loctited but able to rock on the rubber washers, so it self-aligns to a flush seal"},{"id":"b","text":"torqued down solid so it can never move"},{"id":"c","text":"with no washers, metal-to-metal"},{"id":"d","text":"loosely, so it floats freely"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-000000000009', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"A dead mag reads 24V at the supply and through the controller, but 0V at the lock end. That means…","rationale":"24V at the controller but 0V at the lock end means power is lost in the run — a nick or cut."}'::jsonb, '{"choices":[{"id":"a","text":"a nick or cut in the wire run"},{"id":"b","text":"a bad mag lock"},{"id":"c","text":"a dead power supply"},{"id":"d","text":"a tripped controller"}]}'::jsonb, '{"correct":"a"}'::jsonb, false, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-00000000000a', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"Most “dead mag” service calls trace back to…","rationale":"Chase the wire first — a brand-new mag being bad is about one in a million."}'::jsonb, '{"choices":[{"id":"a","text":"the push-button wiring"},{"id":"b","text":"a bad mag lock"},{"id":"c","text":"the controller"},{"id":"d","text":"the card reader"}]}'::jsonb, '{"correct":"a"}'::jsonb, false, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-00000000000b', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"The building has a fire-alarm system. You…","rationale":"The fire-alarm release interface is a specialist job — flag and escalate; don’t wire it on this install."}'::jsonb, '{"choices":[{"id":"a","text":"flag it and escalate — the fire-alarm interface is a specialist job"},{"id":"b","text":"wire the fire-alarm release yourself"},{"id":"c","text":"ignore it; the push-to-exit covers escape"},{"id":"d","text":"disable the mag until someone else handles it"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb),
  ('000000a5-000e-0000-0000-00000000000c', '000000c0-0000-0000-0000-00000000000f', '000000c2-0000-0000-0000-00000000000e', 'mcq', '{"text":"You finish the install. Before sign-off you…","rationale":"The Redex pull test: a properly seated 1,200 lb hold doesn’t budge. If it gives, the armature isn’t sealing."}'::jsonb, '{"choices":[{"id":"a","text":"go outside and pull the door hard to prove the seal and hold"},{"id":"b","text":"call it done — the panel shows locked"},{"id":"c","text":"only check the indicator LED"},{"id":"d","text":"leave the pull test for the evaluator"}]}'::jsonb, '{"correct":"a"}'::jsonb, true, 1.0, '{}'::jsonb)
on conflict (id) do update set
  competency_id = excluded.competency_id, course_version_id = excluded.course_version_id,
  kind = excluded.kind, prompt = excluded.prompt, options = excluded.options,
  answer_key = excluded.answer_key, is_safety_item = excluded.is_safety_item,
  mastery_weight = excluded.mastery_weight, locale_variants = excluded.locale_variants;

