-- ----------------------------------------------------------------------------
-- 4. §5.4 RUBRIC SWAP (M6 finalize-signoff reads this CATALOG to materialize the
--    scored line items). Remove the fire-alarm-release line (the fire-alarm interface
--    is a specialist job — escalated, not wired here) and add the armature-seal
--    pull-test line. 1-for-1 critical swap: still 12 lines / 7 critical — the veto set
--    does NOT shrink (Inv. 1). The veto trigger / RLS / functions are key-agnostic and
--    untouched. Also align the verification line to the pack ("both release modes").
-- ----------------------------------------------------------------------------
delete from academy.signoff_line_item_templates
  where course_id = '000000c1-0000-0000-0000-00000000000e' and line_item_key = 'ac203.release_on_fire_alarm';

insert into academy.signoff_line_item_templates (id, course_id, competency_id, dimension, line_item_key, is_critical_safety, ordinal, label) values
  ('000000b1-000e-0000-0000-000000000003', '000000c1-0000-0000-0000-00000000000e', '000000c0-0000-0000-0000-00000000000f', 'safety_compliance', 'ac203.armature_sealed_pull_test', true, 3, 'Armature sealed — pull test holds')
on conflict (course_id, line_item_key) do update set
