  is_critical_safety = excluded.is_critical_safety, ordinal = excluded.ordinal, label = excluded.label;

update academy.signoff_line_item_templates
  set label = 'Both release modes tested live; pull-test seal proven; logged'
  where course_id = '000000c1-0000-0000-0000-00000000000e' and line_item_key = 'ac203.verify.three_release_modes_logged';

-- ============================================================================
-- 5. POST-CONTENT ASSERTIONS (fail loudly if the AC-203 ingestion is wrong).
-- ============================================================================
do $$
begin
  if (select count(*) from academy.units
        where course_version_id = '000000c2-0000-0000-0000-00000000000e' and kind = 'knowledge_check') <> 1
    then raise exception 'AC-203 knowledge_check unit missing'; end if;
  if (select count(*) from academy.assessment_items where course_version_id = '000000c2-0000-0000-0000-00000000000e') <> 12
    then raise exception 'AC-203 assessment_items <> 12'; end if;
  if (select count(*) from academy.assessment_items where course_version_id = '000000c2-0000-0000-0000-00000000000e' and is_safety_item) <> 9
    then raise exception 'AC-203 safety items <> 9'; end if;
  if (select count(*) from academy.assessment_items where course_version_id = '000000c2-0000-0000-0000-00000000000e' and not is_safety_item) <> 3
    then raise exception 'AC-203 non-safety items <> 3'; end if;
  if exists (select 1 from academy.signoff_line_item_templates
        where course_id = '000000c1-0000-0000-0000-00000000000e' and line_item_key = 'ac203.release_on_fire_alarm')
    then raise exception 'AC-203 fire-alarm rubric line still present'; end if;
  if not exists (select 1 from academy.signoff_line_item_templates
        where course_id = '000000c1-0000-0000-0000-00000000000e' and line_item_key = 'ac203.armature_sealed_pull_test' and is_critical_safety)
    then raise exception 'AC-203 armature-seal critical line missing'; end if;
  if (select count(*) from academy.signoff_line_item_templates where course_id = '000000c1-0000-0000-0000-00000000000e') <> 12
    then raise exception 'AC-203 rubric lines <> 12'; end if;
  if (select count(*) from academy.signoff_line_item_templates where course_id = '000000c1-0000-0000-0000-00000000000e' and is_critical_safety) <> 7
    then raise exception 'AC-203 critical-safety rubric lines <> 7'; end if;
  if (select count(*) from academy.sim_definitions where key like 'ac-203/%' and status = 'published') <> 6
    then raise exception 'AC-203 published sim_definitions <> 6'; end if;
  raise notice 'AC-203 content OK: 1 KC unit / 12 items (9 safety, 3 non-safety) / 6 sims / 12 rubric lines (7 critical, armature swapped in).';
end $$;
